import{_ as s,B as n,o as t,c as r,ax as a,b as l,w as i,a as h,E as d,ah as c}from"./chunks/framework.Bnt0oLax.js";const A=JSON.parse('{"title":"Build & Publish","description":"How widget, script, and stylesheet builds are triggered, processed, and published automatically when you push to your watched branch — no separate preview or promotion step","frontmatter":{"description":"How widget, script, and stylesheet builds are triggered, processed, and published automatically when you push to your watched branch — no separate preview or promotion step"},"headers":[],"relativePath":"custom-widgets/v2/build-and-publish.md","filePath":"custom-widgets/v2/build-and-publish.md"}'),u={name:"custom-widgets/v2/build-and-publish.md"};function p(b,e,m,g,f,w){const o=n("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/build-and-publish.md for this page in Markdown format</div><h1 id="build-publish" tabindex="-1">Build &amp; Publish <a class="header-anchor" href="#build-publish" aria-label="Permalink to &quot;Build &amp; Publish&quot;">​</a></h1><p>Pushing code to your watched branch automatically updates your widgets, scripts, and stylesheets. This page explains the publishing flow and what triggers it.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A connected GitHub organization (see <a href="./connect-github.html">Connect Your GitHub Account</a>)</li><li>At least one enabled repository (see <a href="./repository-settings.html">Repository &amp; Branch Settings</a>)</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When you push changes to a watched branch, your extension content is automatically fetched, processed, and published.</p>',7)),(t(),l(c,null,{default:i(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%221.%20Push%20to%20Watched%20Branch%22%5D%20--%3E%20B%5B%222.%20Change%20Detected%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20Content%20Fetched%20from%20Repository%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20Content%20Validated%20and%20Safety%20Checked%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20Content%20Published%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%226.%20Extensions%20Available%20in%20No-Code%20Builder%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20B%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20C%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20D%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20E%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20F%20fill%3A%23dcfce7%2Cstroke%3A%2322c55e%2Ccolor%3A%231e293b%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="the-push-to-publish-flow" tabindex="-1">The Push-to-Publish Flow <a class="header-anchor" href="#the-push-to-publish-flow" aria-label="Permalink to &quot;The Push-to-Publish Flow&quot;">​</a></h2><h3 id="_1-push-to-watched-branch" tabindex="-1">1. Push to Watched Branch <a class="header-anchor" href="#_1-push-to-watched-branch" aria-label="Permalink to &quot;1. Push to Watched Branch&quot;">​</a></h3><p>When you push a commit to your repository&#39;s watched branch (e.g., <code>main</code>), the platform detects the change automatically.</p><h3 id="_2-change-detection" tabindex="-1">2. Change Detection <a class="header-anchor" href="#_2-change-detection" aria-label="Permalink to &quot;2. Change Detection&quot;">​</a></h3><p>The platform identifies:</p><ul><li>Which repository was updated</li><li>Which branch received the push</li><li>Whether this branch is being watched</li></ul><h3 id="_3-content-fetching" tabindex="-1">3. Content Fetching <a class="header-anchor" href="#_3-content-fetching" aria-label="Permalink to &quot;3. Content Fetching&quot;">​</a></h3><p>If the push was to a watched branch, the platform:</p><ul><li>Fetches the <code>extensions_registry.json</code> file from your repository, which declares your widgets, scripts, and stylesheets</li><li>Downloads widget directories defined in <code>source</code> blocks</li><li>Downloads script and stylesheet files with relative paths</li><li>Validates the content structure</li></ul><h3 id="_4-validation-and-security-check" tabindex="-1">4. Validation and Security Check <a class="header-anchor" href="#_4-validation-and-security-check" aria-label="Permalink to &quot;4. Validation and Security Check&quot;">​</a></h3><p>Valid content is:</p><ul><li>Scanned for security issues (see <a href="./content-security.html">Content Security</a>)</li><li>Processed and optimized</li><li>Validated against the schema</li></ul><h3 id="_5-publishing" tabindex="-1">5. Publishing <a class="header-anchor" href="#_5-publishing" aria-label="Permalink to &quot;5. Publishing&quot;">​</a></h3><p>Validated content is:</p><ul><li>Published to the platform</li><li>Made available in the No-Code Builder and on community pages</li></ul><blockquote><p><strong>Note</strong>: If content hasn&#39;t changed since the last publish, it will be <strong>skipped</strong> rather than re-uploaded. This is normal and improves performance. You&#39;ll see this reflected in the build status details.</p></blockquote><h3 id="_6-extensions-available" tabindex="-1">6. Extensions Available <a class="header-anchor" href="#_6-extensions-available" aria-label="Permalink to &quot;6. Extensions Available&quot;">​</a></h3><p>Your extensions are now:</p><ul><li>Serving new content</li><li>Visible in the No-Code Builder&#39;s widget library</li><li>Ready to be placed on pages by community administrators</li></ul><p>The entire process from push to availability typically completes within seconds for simple extensions.</p><h2 id="what-triggers-publishing" tabindex="-1">What Triggers Publishing <a class="header-anchor" href="#what-triggers-publishing" aria-label="Permalink to &quot;What Triggers Publishing&quot;">​</a></h2><p>Extension publishing is automatically triggered by several actions:</p><table tabindex="0"><thead><tr><th>Action</th><th>What Happens</th></tr></thead><tbody><tr><td><strong>Push to watched branch</strong></td><td>New content is fetched and published</td></tr><tr><td><strong>Enable a repository</strong></td><td>Current content is immediately published</td></tr><tr><td><strong>Change watched branch</strong></td><td><strong>All extensions replaced</strong> with content from the new branch</td></tr><tr><td><strong>Initial connection</strong></td><td>Content is fetched when you first enable a repository</td></tr></tbody></table><p>You don&#39;t need to push a new commit after enabling a repository or changing branches — publishing happens automatically. Which branch is watched is configured in <a href="./repository-settings.html">Repository &amp; Branch Settings</a>.</p><h2 id="branch-based-content" tabindex="-1">Branch-Based Content <a class="header-anchor" href="#branch-based-content" aria-label="Permalink to &quot;Branch-Based Content&quot;">​</a></h2><p>You choose which branch each repository watches in <a href="./repository-settings.html">Repository &amp; Branch Settings</a>. Each repository watches one branch at a time per community; changing it replaces all extensions from that repo. For multi-environment workflows, use separate communities — each watching its own branch.</p><p><strong>Example workflow with separate communities:</strong></p><ol><li>Dev Community watches <code>develop</code> — develop extensions there</li><li>Merge to <code>staging</code> and push — Staging Community picks up changes automatically</li><li>QA team verifies in Staging Community</li><li>Merge to <code>main</code> and push — Production Community picks up changes automatically</li></ol><p>For a step-by-step guide, see <a href="./../recipes/preview-and-promote.html">Preview and Promote</a>.</p><h2 id="build-status" tabindex="-1">Build Status <a class="header-anchor" href="#build-status" aria-label="Permalink to &quot;Build Status&quot;">​</a></h2><p>Each publishing attempt shows a status (In Progress, Completed, Warning, Failed) in Sources. A <strong>Warning</strong> status means the build succeeded and your content is live, but advisories — such as deprecation notices — need your attention. Click the status indicator to see the full error details for failed builds or the advisory list for builds with warnings. For what each status means and how to act on it, see <a href="./repository-settings.html#step-6-understanding-build-status">Repository &amp; Branch Settings — Understanding Build Status</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>For troubleshooting failed, stuck, or stale builds — including why a push didn&#39;t update your extensions, why fewer extensions published than expected, and content that appears out of date — see <a href="./common-issues.html">Common Issues</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./multiple-organizations.html">Multiple Organizations</a> — Work with multiple GitHub organizations</li><li><a href="./../recipes/preview-and-promote.html">Recipes: Preview and Promote</a> — Preview builds before going to production</li><li><a href="./../recipes/force-republish.html">Recipes: Force Republish</a> — Trigger a rebuild without a code change</li><li><a href="./error-codes.html">Error Codes</a> — Full error reference for build failures</li><li><a href="./common-issues.html">Common Issues</a> — Resolve common issues</li></ul>',35))])}const C=s(u,[["render",p]]);export{A as __pageData,C as default};
